order.code:
const es = self.nearbyEnemies().filter(e => !e.isBuilding && e.y < 13 && e.x < 13);
let t = null, d = 99;
for (const e of es) { const k = self.distanceTo(e); if (k < d) { d = k; t = e; } }
if (!t) { const e = self.enemiesInRange()[0]; if (e && !e.isBuilding) { self.attack(e); } else self.hold(); }
else if (d <= self.range) self.attack(t);
else self.moveTo(t.x, t.y);
